"""Render final report only from saved campaign data; never run simulations."""
import json,pathlib,csv,collections,itertools
import numpy as np
from analyze import load,metrics,pairs,mechanism,export
D=pathlib.Path(__file__).resolve().parent
M=json.loads((D/'manifest.json').read_text())
def table(rows):
 out=['| Candidate | Finishes | Completion, exact 95% CI | Penalized s | Success mean / p90 s | Failed / fallback ticks | Mean / p99 ms | >20 ms calls |','|---|---:|---|---:|---|---|---|---:|']
 for r in rows:out.append(f"| {r['candidate']} | {r['finishes']}/{r['n']} | {100*r['completion']:.1f}% [{100*r['ci_lower']:.1f}, {100*r['ci_upper']:.1f}] | {r['penalized_mean_s']:.3f} | {r['successful_mean_s']:.3f} / {r['successful_p90_s']:.3f} | {r['failed_solver_ticks']} / {r['fallback_ticks']} | {r['compute_mean_ms']:.3f} / {r['compute_p99_ms']:.3f} | {r['deadline_overruns']} |")
 return '\n'.join(out)
def main():
 stages={s:load(s) for s in ['A','B','C']};rr={s:metrics(s,x) for s,x in stages.items() if x};pr={s:pairs(s,x) for s,x in stages.items() if x}
 if 'C' not in rr:raise ValueError('Final confirmation not yet available')
 c=rr['C'];winner=c[0];alt=c[1:];full=all(r['n']==500 for r in c) and len(c)==3
 assert full,'No final report before complete independent evaluation'
 names=[r['candidate'] for r in c];fast=min(c,key=lambda r:r['successful_mean_s']);efficient=min(c,key=lambda r:r['compute_mean_ms'])
 lines=['# MPCC comparative campaign — final technical report','',f"## 1. Recommendation\n\n**Primary recommendation: {winner['candidate']}**, `{winner['configuration_id']}`, using the complete frozen settings in manifest.json. It has the highest observed final-stage completion in this campaign: {winner['finishes']}/{winner['n']} ({winner['completion']:.1%}), exact 95% CI [{winner['ci_lower']:.1%}, {winner['ci_upper']:.1%}], with {winner['penalized_mean_s']:.3f} s failure-penalized mean. This ordering describes observed results; the paired evidence below determines whether a superiority claim is supported. Do not interpret an ordinal rank as a statistically established winner.",f"Strong alternatives: {', '.join(names[1:])}. F1_2 is the strongest balanced alternative, with fewer observed fallback episodes and faster successful races; population-rate differences remain uncertain. The maximum-observed-robustness choice is {winner['candidate']}; the fastest final-stage successful mean is {fast['candidate']} ({fast['successful_mean_s']:.3f} s); the lowest observed mean controller cost is {efficient['candidate']} ({efficient['compute_mean_ms']:.3f} ms). Speed and compute alternatives are restricted to confirmed finalists; screening-only candidates do not receive equivalent validation status.",'## 2. Selection and historical evidence','', 'Ten runnable configurations were selected from the resolved official-core group before new race outcomes were inspected. See candidate_selection.md. All ten supplied suggestions were retained: the three 84/100 leaders, two E09 weights, G01 gate offset, E02 contour cost, F2, REF, and RECHECK_R24. The E09 pair tests sensitivity to weighting despite identical historical finish counts. F1/F1_2 directly tests offsets 0.180/0.162. Small-n apparent leaders and redundant multi-change relatives were excluded. The prior comprehensive audit (106 PASS, 0 FAIL, 33 NOT_VERIFIED) was not repeated. Targeted implementation/environment hash checks were necessary to reconstruct runnable controllers.','', 'The retained 596-cohort/420-configuration assessment, its configuration/cohort metrics, paired comparisons, validation comparisons, data dictionary, phase-4 direct F1 review, and original pinned source snapshots informed selection. Independent validation often reduced earlier completion estimates; fresh confirmation therefore takes precedence. Historical modified-core candidates (including incumbent and opt_a758e8cb3e87) remain in historical_modified_candidates.json with their own environment identities. Their legacy implementations, source environments, much slower trajectories and incomplete timing closure preclude direct pooling. They were considered but not promoted into this ten-candidate campaign. No claim that they are inferior under the new environment follows from their exclusion.','', 'The seven alpha rankings are exploratory, correlated indicators. Original numeric alpha_5/10/15/20/25/30/50 artifacts were not located in retained docs/research; their columns are missing rather than fabricated. Selection uses underlying completion, confidence bounds, time, health, sample size, and source identity. This is a limitation in recovering the requested contextual ranking data.','## 3. Design and controls','', 'Stage A: 10 × 100; Stage B: 5 × 200; Stage C: 3 × 500, for 3,500 measured races. These runtime-adjusted sizes were frozen in runtime_design.json before A. Rebuilt episodes cost about 5 s; validated build reuse reduced this to about 1 s. Increasing independent sample sizes reserve most evidence for confirmation. Individual n=500 completion intervals near 80% have roughly ±4 percentage points uncertainty. Small differences can remain unresolved. There was no outcome-dependent stopping or parameter tuning.','', 'Selection rule at A and B: descending finishes, ascending 30-second-penalized mean, ascending failed solver ticks, then ascending pooled call p99. Five finalists then three finalists were selected. Configurations and all seed lists were frozen before collection; stage-specific plan files and SHA256 files identify actual prefixes. Stage C was not inspected for candidate selection or tuning. Source and library hashes are checked on each launch.','', 'All simulations use the isolated retained official-core source package, CPU JAX, 50 Hz attitude interface, 500 Hz dynamics, nominal Level 2 gate order, original randomizations and disturbances. The active repository simulator/configuration was not changed. This is a new fully specified runtime environment, not proof of historical binary equivalence; historical and new samples are not pooled. Full package versions, hardware/CPU affinity, source and library pins, runtime origins, and git state are retained in provenance.json, manifest.json and per-stage runtime.json. Desktop background load was not eliminated; timings are serial and comparable in workload but not hard-real-time certification.','', 'Fresh deterministic seeds were generated with NumPy seed 202611121739 and checked against all explicit seeds recoverable from normalized retained evidence. Full reset EnvData tree arrays, including randomized hidden track/dynamics and PRNG state, are stored in states/*.npz with dtype/shape-sensitive SHA256 hashes. Hash equality is asserted across candidates on every paired seed. Float arrays and initial observations are retained; unknown external/unretained seed usage cannot be excluded. Seed order is shared and candidate order rotates by seed to spread load drift.','', 'Each controller is newly constructed each race. Build reuse caches a separate solver per exact settings identity and updates the path-length bounds for each new initial position. No controller computation or official physics source was edited. All ten × three smoke outcomes and terminal observations agreed with rebuilding; six F1/REF action traces were additionally checked: maximum float64 difference <5e-15 and every float32 action exactly identical. See cache_validation.json and cache_trace_validation.json. Smoke and technical trace data are excluded from performance estimates. This finite check is evidence of immaterial behavior change, not a mathematical proof for every possible state.','', 'Race time is completed control steps / 50, matching the retained study convention. Original zero-based official time is also saved per episode (one 20 ms tick lower). Failed races score 30 s regardless of observed failure duration. Whole compute_control calls are timed, excluding solver construction, simulator steps, callbacks and terminal diagnostics; pooled p99 and >20 ms counts use all calls, including failed races. Fallback is explicitly observed at the unique hover branch (_prediction is None), verified against source; solver status is saved per tick. Internal QP iteration histories and each RTI subsolve are not collected, so failed_solver_ticks counts final reported nonzero status ticks, not iterations. Missing telemetry is never interpreted as zero.','## 4. Results by stage','']
 for s in ['A','B','C']:lines += [f'### Stage {s}', '',table(rr[s]),'']
 lines+=['## 5. Paired comparisons and uncertainty','', 'All comparisons are candidate minus reference; positive completion differences favor the candidate and negative time differences favor it. Completion differences use conservative paired intervals formed from Bonferroni exact rescue/regression cell bounds. This interval has at least 95% coverage under iid paired episodes; bootstrap completion intervals are also retained as exploratory summaries. Exact two-sided McNemar p-values are Holm-adjusted over all pairs within each stage (45, 10, and 3). Penalized and shared-success mean differences use 10,000 deterministic paired bootstrap resamples. Those time intervals are pointwise; they do not establish simultaneous significance. Practical reference margins are 3 percentage points completion and 0.5 s penalized time; failure to reject a difference is not evidence of equivalence.','', '| Stage C: reference → candidate | Rescues / regressions | Completion Δ pp [95% CI] | Holm p | Penalized Δ s [95% bootstrap CI] | Shared-success Δ s [95% CI], n |','|---|---|---|---|---|---|']
 for r in pr['C']:lines.append(f"| {r['reference']} → {r['candidate']} | {r['rescues']} / {r['regressions']} | {100*r['completion_difference']:.2f} [{100*r['completion_ci_lower']:.2f}, {100*r['completion_ci_upper']:.2f}] | {r['mcnemar_holm_p']:.4g} | {r['penalized_delta_s']:.3f} [{r['penalized_ci_lower']:.3f}, {r['penalized_ci_upper']:.3f}] | {r['successful_delta_s']:.4f} [{r['successful_ci_lower']:.4f}, {r['successful_ci_upper']:.4f}], {r['shared_success_n']} |")
 lines+=['', 'All A/B paired comparisons, including F1 references where retained, are in paired_comparisons.csv. Stage A and B are selection evidence; C alone supplies final independent evaluation. Success-only comparisons condition on joint completion and cannot replace unconditional completion or penalized time.','## 6. Practical interpretation','']
 for r in pr['C']:
  significant=r['mcnemar_holm_p']<.05
  within=r['completion_ci_lower']>-.03 and r['completion_ci_upper']<.03
  lines.append(f"{r['reference']} versus {r['candidate']}: {'a completion difference is supported after Holm adjustment' if significant else 'no completion superiority is established after Holm adjustment'}. {'The conservative paired interval lies within the ±3 pp practical margin.' if within else 'The conservative paired interval does not establish practical equivalence within ±3 pp.'}")
 lines+=['','## 7. Failure mechanisms and starting conditions','', 'The official environment warps disabled drones to [-1,-1,-1], so terminal observations cannot identify the impact. A read-only replay of the final pre-step state and action recovers pre-warp position and contacts using official action disturbance, dynamics and collision functions. The replay does not affect controller or simulator continuation. Contact geometry/body identifiers, penetration distances and prewarp position are saved. Contact classifications are diagnostic replay evidence; failures without recovered gate/pole contacts are kept unresolved rather than assigned a fabricated mechanism. Upper-frame classification depends on geometry names; unclassified gate frames remain in the gate-contact category.','']
 failures=[]
 for st,x in stages.items():
  for name,rs in x.items():
   co=collections.Counter(mechanism(r) for r in rs)
   failures.append(dict(stage=st,candidate=name,**{k:co[k] for k in ['success','gate_contact','pole_contact','timeout','bounds_or_unresolved_contact']}))
 export(D/'failure_mechanisms.csv',failures)
 lines+=['| Stage / candidate | Gate | Pole | Timeout | Bounds / unresolved |','|---|---:|---:|---:|---:|']
 for r in failures:lines.append(f"| {r['stage']} / {r['candidate']} | {r['gate_contact']} | {r['pole_contact']} | {r['timeout']} | {r['bounds_or_unresolved_contact']} |")
 lines+=['','Starting-condition strata and per-seed difficulty are exploratory diagnostics, not new independent tests. failure_analysis.csv retains initial position, gate progress and terminal coordinates; prewarp positions and contact bodies are in episode JSON. Initial-condition effects may reflect randomized hidden gates, mass and inertia as well as starting pose. A single-variable association cannot establish causation.','## 8. Numerical and computational reliability','', 'numerical_computational_health.csv gives full measured coverage for every candidate/stage. All configurations share broad-core implementation complexity 2, using two RTI passes, gate-path deformation, pole avoidance and thrust adaptation. Parameter-only changes do not change implementation complexity. A failed tick can recover without losing the race; race completion does not erase such events. Explicit fallback and nonzero solver status counts are separate. Historical G07 had 13 failed ticks across three screening episodes; the new tables establish whether that concern recurs. Deadline overruns use the 20 ms controller period. Pooled p99 is computed from raw per-call samples, never averaged from episode percentiles.','## 9. Historical comparison','', 'Historical official screening F1/F1_2/G07 each finished 84/100; F1_2 rescued two and regressed two against F1, with only a 5.6 ms shared-success advantage and missing initial-state vectors. The new campaign supplies verified state pairing and independent selection/confirmation. Apparent historical gains may regress after selection, and raw rates across disjoint cohorts need uncertainty. Historical modified-core completion/time evidence remains environment-specific. Its conditional box-contact fix is absent here.','## 10. Limitations','', 'Only the nominal Level 2 randomization distribution was tested. No hardware flight, alternative track, wind-domain shift, multi-drone traffic or GPU timing validation is implied. The reduced screening/confirmation sizes provide less precision than the initial 200/500/1000 framework. Three finalists give limited independent coverage of eliminated candidates. Pointwise time bootstrap intervals and exploratory failure strata are not multiplicity-corrected causal evidence. Full initial-state arrays support replay but cross-version deterministic equivalence is not guaranteed. Source files and shared libraries are frozen; package manifests do not prove every system library/kernel instruction path identical to historical experiments. Build-reuse equivalence was tested on finite smoke cases. Original numeric alpha scores were unavailable. The final recommendation is restricted to the tested distribution and environment.','## 11. Deployment choice','',f"Use **{winner['candidate']}** as the primary practical foundation under the frozen environment. Preserve its entire settings object and verified implementation bundle; copying the case name or gate-offset value alone is insufficient. Alternatives are {', '.join(names[1:])}; use the paired uncertainty above to decide whether selecting one is a practical preference within unresolved differences. Speed choice: {fast['candidate']}; measured mean-cost choice: {efficient['candidate']}. No speed recommendation overrides a material completion disadvantage.",'## 12. Reproduction','', 'From the repository root (the campaign source snapshot is already frozen):','```bash','export LD_LIBRARY_PATH="$PWD/acados/lib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"','.pixi/envs/default/bin/python docs/control/mpcc_campaign_20261112_v1/orchestrate.py','.pixi/envs/default/bin/python docs/control/mpcc_campaign_20261112_v1/finalize.py','```','The orchestrator resumes missing episode files and refuses changed frozen plans/sources. To rerun from scratch, copy the campaign to a new sibling directory and remove A/B/C, selection_B/C.json and their hashes, orchestration logs and generated summaries in that copy; retain manifest, seeds, source, runtime_design and validation evidence. Do not rerun prepare.py over an existing campaign. Individual stage commands are `run.py --stage A --cache` (then B/C after frozen selections). Exact prefix seed lists are in stage plan.json; full reserved lists are seeds_A/B/C.json. Raw episode JSON includes actions, timing arrays, numerical status, settings hash, exact-state reference and execution timestamp. CSVs and charts are derived artifacts; original assessment/data remain untouched.']
 lines+=['## Additional technical interpretation','', (D/'source_interpretation.md').read_text().split('\n',2)[-1], '']
 if 'B' in rr:
  rb={r['candidate']:r for r in rr['B']}
  if 'RECHECK_R24' in rb and 'F1' in rb:
   lines.append(f"The faster RECHECK_R24 trades {100*(rb['F1']['completion']-rb['RECHECK_R24']['completion']):.1f} percentage points of Stage B completion against {rb['F1']['successful_mean_s']-rb['RECHECK_R24']['successful_mean_s']:.3f} s of conditional successful time. That trade-off does not justify replacing the stronger completion candidates for this task.")
 for st in ['A','B','C']:
  row=next((r for r in rr[st] if r['candidate']=='G07_pole_width_0p4375'),None)
  if row:lines.append(f"G07 Stage {st}: {row['solver_affected_episodes']}/{row['n']} episodes with nonzero solver status, {row['failed_solver_ticks']} failed ticks and {row['fallback_ticks']} fallback activations. The historical 13-tick concern must be interpreted against these fresh observations rather than assumed to recur at its original rate.")
 lines.append('Stage A reference contrasts (exploratory selection evidence):')
 for r in pr['A']:
  if (r['reference'],r['candidate']) in [('F1','REF'),('G07_pole_width_0p4375','REF'),('E09_attitude_rate_weight_0p05','F1')]:
   lines.append(f"{r['reference']} → {r['candidate']}: {r['rescues']} rescues, {r['regressions']} regressions; completion difference {100*r['completion_difference']:.1f} pp; Holm-adjusted exact p={r['mcnemar_holm_p']:.5g}.")
 lines+=['## Numerical replay and environment diagnosis','', 'All 11 numerically affected measured episodes were replayed with isolated fresh solver builds. Every replay reproduced the original float32 actions, race steps, outcomes and fallback counts exactly. The initial diagnostic library-reuse issue and its correction are documented in infrastructure_notes.md; its archived nonisolated outputs are excluded from inference. A cached-build control replay is retained separately. The additional getter instrumentation is outside measured timing data.', 'All first fallback states had at least one measured Euler angle outside the configured ±0.7-radian hard state bound. The captured subsolve returned acados QP_FAILURE=4 with HPIPM NAN_SOL=3. This supports a hypothesis of numerical difficulty near infeasible attitude-bound recovery; it does not prove which constraint caused failure. Ten of the 11 affected races ultimately finished. Broadening/softening bounds would be a new exploratory tuning campaign and was not done on confirmation seeds.', 'The initialization RuntimeWarning was traced separately to MuJoCo 3.10.0 box-box collision code converting jp.finfo(float).max into the active float32 dtype. No simulator patch or precision change was applied. It is an environment-level collision-sentinel warning rather than an observed controller-output NaN. Its presence does not establish collision correctness or harmlessness; results remain specific to this frozen official-core/runtime combination. See initialization_warning_trace.txt.', 'Numerical-event exact intervals and paired tests are in health_confidence_intervals.csv and paired_health_comparisons.csv. In the final stage, G07 had 6/500 affected episodes, F1 2/500, and F1_2 1/500. The larger observed G07 burden recurs, but sparse event counts limit inference about population-rate differences.', 'Mechanistic paired evidence: against F1, G07 rescued 38 final-stage seeds (27 pole failures and 11 gate failures in F1) and regressed on 20 seeds, all gate-contact failures in G07. This supports a pole-versus-gate trade-off rather than universal dominance. Upper-frame cluster counts were 19 G07, 12 F1, and 12 F1_2; cluster labels can overlap within a failed episode. Across all three finalists, 58/500 seeds defeated every controller and 377/500 were finished by all three.', "Exploratory starting-condition sensitivity: in the second quartile of initial x (approximately [-1.5477, -1.4981) m), G07 finished 109/125, F1_2 100/125, and F1 97/125. That stratum accounts for nine of G07's ten net additional finishes versus F1_2 and 12 of its 18 versus F1. The observed gain is concentrated, rather than uniform across starting positions. This post-hoc subgroup comparison is not multiplicity-adjusted or causal: hidden gate/dynamics randomizations and chance can explain associations. It limits extrapolation to changed starting distributions; no tuning was performed from these strata.", 'F1_2 versus F1 rescued 14 and regressed six final-stage seeds. The smaller gate offset yielded a 1.6 pp observed gain, but conservative paired 95% bounds [-1.41, 4.57] pp and Holm p=0.231 do not establish robustness superiority or ±3 pp equivalence. Its shared-success speed advantage was only 4.9 ms. The final-stage mean compute differences between finalists have paired bootstrap intervals spanning zero, so no meaningful computational-efficiency winner is established.']
 runtime=json.loads((D/'C/runtime.json').read_text())
 cpu=next((s.split(':',1)[-1].strip() for s in M['hardware']['cpu'].splitlines() if 'model name' in s),'unknown')
 lines.insert(lines.index('## 3. Design and controls')+1,'Hardware: '+cpu+'. Python '+runtime['python'].split()[0]+'. Runtime versions: '+', '.join(k+' '+v for k,v in runtime['versions'].items())+'. CPU JAX; BLAS/OpenMP thread counts fixed to one.')
 winpairs=[p for p in pr['C'] if winner['candidate'] in [p['reference'],p['candidate']]]
 unique=all(p['mcnemar_holm_p']<.05 and (p['completion_difference']>0 if p['candidate']==winner['candidate'] else p['completion_difference']<0) for p in winpairs)
 lines.insert(3,'**Completion superiority:** '+('The primary candidate beats both other finalists in the final-stage exact paired tests after Holm correction; practical margins still require the reported intervals.' if unique else 'No unique completion winner is established against all finalists. The primary recommendation is a practical default within unresolved differences, not a claim of proven superiority or equivalence.'))
 confirmed=next(r for r in csv.DictReader((D/'final_rankings.csv').open()) if r['stage']=='C' and r['candidate']==winner['candidate'])
 (D/'recommended_configuration.json').write_text(json.dumps(dict(candidate=winner['candidate'],configuration_id=winner['configuration_id'],campaign_configuration_id=confirmed['campaign_configuration_id'],comparison_environment_sha256=confirmed['comparison_environment_sha256'],settings=M['candidates'][winner['candidate']]['settings'],implementation='source/lsy_drone_racing/control/mpcc_broad_core.py:MPCCBroadCore',manifest_sha256=(D/'manifest.sha256').read_text().strip(),unique_completion_superiority_supported=unique),indent=2))
 body='\n\n'.join(lines).replace('|\n\n|','|\n|')
 while '\n\n\n' in body:body=body.replace('\n\n\n','\n\n')
 body+='\n\nThe empirical Pareto frontier among confirmed finalists is G07 and F1_2: G07 has the highest completion and lowest penalized-time point estimates; F1_2 has faster successful races and fewer observed fallback events. F1 is dominated on these point estimates, but population dominance is not established.\n\n![Final-stage trade-offs](final_tradeoffs.png)'
 (D/'final_report.md').write_text(body+'\n\n![Completion intervals by stage](completion_intervals.png)\n\n[Detailed technical findings](technical_findings.md); [Failure clusters](failure_clusters.csv); [Starting-condition sensitivity](initial_condition_sensitivity.csv); [Paired compute comparisons](paired_compute_comparisons.csv); [Artifact audit](audit.json).\n')
 try:
  import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
  fig,axs=plt.subplots(1,3,figsize=(19,5))
  for ax,st in zip(axs,['A','B','C']):
   rows=rr[st];v=np.array([r['completion'] for r in rows]);lo=np.array([r['ci_lower'] for r in rows]);hi=np.array([r['ci_upper'] for r in rows]);ax.errorbar(v,np.arange(len(rows)),xerr=[v-lo,hi-v],fmt='o');ax.set_yticks(np.arange(len(rows)),[r['candidate'] for r in rows],fontsize=7);ax.invert_yaxis();ax.set_xlim(.4,1);ax.set_xlabel('Completion probability');ax.set_title(f'Stage {st}: exact 95% intervals');ax.grid(axis='x',alpha=.3)
  fig.tight_layout();fig.savefig(D/'completion_intervals.png',dpi=180);plt.close(fig)
  fig,axs=plt.subplots(1,2,figsize=(11,5))
  from scipy.stats import beta
  for r in c:
   label='G07' if r['candidate'].startswith('G07') else r['candidate'];y=r['completion'];ye=[[y-r['ci_lower']],[r['ci_upper']-y]]
   axs[0].errorbar(r['successful_mean_s'],y,yerr=ye,fmt='o');axs[0].annotate(label,(r['successful_mean_s'],y),xytext=(5,5),textcoords='offset points')
   k=r['fallback_affected_episodes'];n=r['n'];p=k/n;lo=beta.ppf(.025,k,n-k+1) if k else 0;hi=beta.ppf(.975,k+1,n-k) if k<n else 1
   axs[1].errorbar(p,y,xerr=[[p-lo],[hi-p]],yerr=ye,fmt='o');axs[1].annotate(label,(p,y),xytext=(5,5),textcoords='offset points')
  axs[0].set_xlabel('Successful mean race time (s; conditional)');axs[1].set_xlabel('Fraction of episodes with fallback')
  for ax in axs:ax.set_ylabel('Completion probability');ax.grid(alpha=.3)
  fig.suptitle('Independent final-stage trade-offs; exact 95% rate intervals');fig.tight_layout();fig.savefig(D/'final_tradeoffs.png',dpi=180);plt.close(fig)

 except ImportError:(D/'chart_unavailable.txt').write_text('matplotlib unavailable in existing environment')
if __name__=='__main__':main()
